#[inline(always)]
unsafe fn DecodeSymbol(
    mut bits: uint64_t,
    mut table: *const HuffmanCode,
    mut br: *mut BrotliBitReader,
) -> uint64_t {
    // SAFETY: `table` points to a Huffman decoding table whose first-level
    // region has at least 256 entries; this function probes entry `bits & 0xff`
    // exactly as the original raw-pointer code did, and no Rust references to
    // the same memory are created elsewhere in this region.
    let table_slice = unsafe { core::slice::from_raw_parts(table, 256) };
    let first = unsafe { table_slice.get_unchecked((bits & 0xff as uint64_t) as usize) };
    let first_bits = first.bits;
    let first_value = first.value;

    if first_bits as c_uint > HUFFMAN_TABLE_BITS {
        let nbits: uint64_t =
            (first_bits as c_uint).wrapping_sub(HUFFMAN_TABLE_BITS) as uint64_t;
        BrotliDropBits(br, HUFFMAN_TABLE_BITS as uint64_t);
        let second_index =
            (first_value as uint64_t).wrapping_add(bits >> 8 as c_uint & BitMask(nbits)) as isize;
        table = table.offset(second_index);
    } else {
        table = first as *const HuffmanCode;
    }

    let final_bits = (*table).bits;
    let final_value = (*table).value;
    BrotliDropBits(br, final_bits as uint64_t);
    final_value as uint64_t
}

